        n = get(instance, "n", get(instance, "num_customers", get(instance, "size", None)))
        if n is None:
            if dist is not None:
                n = len(dist) - 1
            elif coords is not None:
                n = len(coords) - 1
            else:
                n = len(to_list(demands)) - 1
        customers = [i for i in range(1, int(n) + 1)]
    else:
        customers = [c for c in to_list(customers) if c != depot]

    if not customers:
        return []

    def load(route):
        s = 0
        for c in route:
            s += dem(c)
        return s

    def route_cost(route):
        if not route:
            return 0.0
        total = d(depot, route[0])
        for a, b in zip(route, route[1:]):
            total += d(a, b)
        total += d(route[-1], depot)
        return total

    def insert_delta(route, pos, c):
        a = depot if pos == 0 else route[pos - 1]
        b = depot if pos == len(route) else route[pos]
        return d(a, c) + d(c, b) - d(a, b)

    def two_opt_best(route):
        n = len(route)
        best_gain = 0.0
        best = None
        base = route_cost(route)
        for i in range(n - 1):
            for j in range(i + 1, n):
                cand = route[:i] + route[i:j + 1][::-1] + route[j + 1:]
                cst = route_cost(cand)
                gain = base - cst
                if gain > best_gain + 1e-12:
                    best_gain = gain
                    best = cand
        if best is None:
            return route, False
        return best, True

    def best_insert_route(route, c):
        best_pos = 0
        best_val = None
        for pos in range(len(route) + 1):
            v = insert_delta(route, pos, c)
            if best_val is None or v < best_val - 1e-12 or (abs(v - best_val) <= 1e-12 and pos < best_pos):
                best_val = v
                best_pos = pos
        return best_pos

    customers = sorted(customers, key=lambda c: (-dem(c), c))

    routes = []
    for c in customers:
        best_choice = None
        best_metric = None
        for ri in range(len(routes)):
            r = routes[ri]
            if load(r) + dem(c) > cap:
                continue
            pos = best_insert_route(r, c)
            metric = (insert_delta(r, pos, c), len(r), ri, pos)
            if best_metric is None or metric < best_metric:
                best_metric = metric
                best_choice = (ri, pos)
        if best_choice is None:
            routes.append([c])
        else:
            ri, pos = best_choice
            routes[ri].insert(pos, c)

    for _ in range(3):
        improved = True
        while improved:
            improved = False

            i = 0
            while i < len(routes):
                nr, ok = two_opt_best(routes[i])
                if ok and route_cost(nr) + 1e-12 < route_cost(routes[i]):
                    routes[i] = nr
                    improved = True
                i += 1
            if improved:
                continue

            moved = False
            i = 0
            while i < len(routes) and not moved:
                r1 = routes[i]
                a = 0
                while a < len(r1) and not moved:
                    c = r1[a]
                    j = 0
                    while j < len(routes) and not moved:
                        if i != j:
                            r2 = routes[j]
                            if load(r2) + dem(c) <= cap:
                                base = route_cost(r1) + route_cost(r2)
                                r1_removed = r1[:a] + r1[a + 1:]
                                pos = best_insert_route(r2, c)
                                r2_added = r2[:pos] + [c] + r2[pos:]
                                if load(r1_removed) <= cap and load(r2_added) <= cap:
                                    new_cost = route_cost(r1_removed) + route_cost(r2_added)
                                    if new_cost + 1e-12 < base:
                                        routes[i] = r1_removed
                                        routes[j] = r2_added
                                        moved = True
                                        improved = True
                        j += 1
                    a += 1
                i += 1
            if improved:
                continue

            merged = False
            i = 0
            while i < len(routes) and not merged:
                j = i + 1
                while j < len(routes) and not merged:
                    r1 = routes[i]
                    r2 = routes[j]
                    if load(r1) + load(r2) <= cap:
                        best = None
                        best_cost = None
                        for rev1 in (False, True):
                            rr1 = r1[::-1] if rev1 else r1
                            for rev2 in (False, True):
                                rr2 = r2[::-1] if rev2 else r2
                                cand = rr1 + rr2
                                cst = route_cost(cand)
                                if best_cost is None or cst < best_cost - 1e-12:
                                    best_cost = cst
                                    best = cand
                        if best_cost + 1e-12 < route_cost(r1) + route_cost(r2):
                            routes[i] = best
                            routes.pop(j)
                            merged = True
                            improved = True
                    j += 1
                i += 1

    seen = {}
    for r in routes:
        for c in r:
            seen[c] = seen.get(c, 0) + 1

    missing = []
    for c in customers:
        if seen.get(c, 0) == 0:
            missing.append(c)

    if missing:
        for c in sorted(missing, key=lambda x: (-dem(x), x)):
            best = None
            best_metric = None
            for ri in range(len(routes)):
                if load(routes[ri]) + dem(c) > cap:
                    continue
                pos = best_insert_route(routes[ri], c)
                metric = (insert_delta(routes[ri], pos, c), len(routes[ri]), ri, pos)
                if best_metric is None or metric < best_metric:
                    best_metric = metric
                    best = (ri, pos)
            if best is None:
                routes.append([c])
            else:
                ri, pos = best
                routes[ri].insert(pos, c)

    cleaned = []
    for r in routes:
        rr = [c for c in r if c != depot]
        if rr:
            cleaned.append(rr)

    routes = cleaned
    return routes
